package com.smeventaura.backend.exception;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.Map;@RestControllerAdvice public class GlobalExceptionHandler{@ExceptionHandler(Exception.class)ResponseEntity<?> handle(Exception e){return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(Map.of("message","Server error. Please try again."));}}
